function Scenario() {
  switch (scenario) {
    case 'skills':return <SkillsScreen/>;
    case 'badges':return <BadgesScreen/>;
    case 'fonts':return <FontSettingsScreen/>;
    case 'aisettings':return <AISettingsScreen/>;
    case 'syncsettings':return <SyncSettingsScreen/>;
    case 'ttssettings':return <TTSSettingsScreen/>;
    case 'vectorsettings':return <VectorModelSettingsScreen/>;
    case 'feedback':return <FeedbackScreen/>;
    case 'webdavbrowser':return <WebDavImportBrowserScreen route={{key:'WebDavImportBrowser',name:'WebDavImportBrowser',params:{source:{kind:'temporary',url:'https://memory.invalid',username:'fixture',password:'memory'}}}} navigation={nav as NativeStackNavigationProp<RootStackParamList,'WebDavImportBrowser'>}/>;
    case 'stats':return <StatsScreen/>;
    case 'profile':return <ProfileScreen/>;
    case 'library':return <LibraryScreen/>;
    case 'notes':return <NotesView/>;
    case 'details':return <BookDetailsScreen route={{key:'Details',name:'BookDetails',params:{bookId:'book-1'}}} navigation={nav as NativeStackNavigationProp<RootStackParamList,'BookDetails'>}/>;
