    case "chat":
      return <ChatScreen />;
    case "bookchat":
      return (
        <BookChatScreen
          route={{
            key: "BookChat",
            name: "BookChat",
            params: {
              bookId: "book-1",
              selectedText:
                "第一行选中的正文。\n第二行继续选中的正文内容。\n第三行还有更多选中的文字。\n第四行是最后一行选中文字。",
              chapterTitle: "第一章 折叠外屏",
            },
          }}
          navigation={nav as NativeStackNavigationProp<RootStackParamList,'BookChat'>}
        />
      );
    case "appearance":
      return <AppearanceSettingsScreen />;
    case "translationsettings":
      return <TranslationSettingsScreen />;
    case "groups":
      return (
        <GroupPickerSheet
          visible
          groups={groups}
          currentGroupId="g-1"
          onSelect={call('group-select')}
          onCreateGroup={call('group-create')}
          onClose={call('close')}
        />
      );
    case "bookmenu":
      return (
        <BookCardActionSheet
          visible
          anchor={anchorAtBottom}
          book={testBook}
          onClose={call('close')}
          onShowDetails={call('details')}
          onManageTags={call('tags')}
          onVectorize={call('vectorize')}
          onDelete={call('delete')}
        />
      );
    default:
      return <Text>unknown scenario</Text>;
  }
}

createRoot(document.getElementById("root")!).render(
  <SafeAreaProvider
    initialMetrics={{
      frame: { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight },
